import { test, expect } from '@playwright/test';

test.describe('Password Requirements Tooltip', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/login'); // Replace with the actual URL
  });

  test('should display tooltip on password field focus', async ({ page }) => {
    const passwordInput = page.getByLabel('Password');
    await passwordInput.focus();
    const tooltip = page.getByText('Password must be at least 8 characters long, include an uppercase letter, a number, and a special character.');
    await expect(tooltip).toBeVisible();
  });

  test('should not display tooltip when password field is not focused', async ({ page }) => {
    const passwordInput = page.getByLabel('Password');
    await passwordInput.blur();
    const tooltip = page.getByText('Password must be at least 8 characters long, include an uppercase letter, a number, and a special character.');
    await expect(tooltip).not.toBeVisible();
  });
});
